    private static String s(Map<String,Object> r,String k){return r.get(k)==null?null:r.get(k).toString();}
    private static long n(Map<String,Object> r,String k){return ((Number)r.get(k)).longValue();}
    private static UUID u(Object v){return UUID.fromString(v.toString());}
    private String hash(Object value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(value)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
    private void guard(Operador a){db.sql.queryForObject("SELECT id FROM identity_guard WHERE id=1 FOR UPDATE",Integer.class);core.bloquearAcceso(a);}
    private String persona(String actor){if(autoridad==null)throw new FalloTecnico(409,"AUTORIDAD_RESERVA_NO_ACREDITADA");return autoridad.contextoReserva(actor).persona();}
    private void motivo(String value){try{cl.nexbyte.siger.contrato.DeclaracionNna.texto(value==null?null:value.replace('\r',' ').replace('\n',' '),2000,true);}catch(IllegalArgumentException e){throw new FalloTecnico(400);}}
    private void version(Map<String,Object> r,long version){if(version<0||n(r,"revision")!=version)throw new FalloTecnico(409,"VERSION_OBSOLETA");}
    private Map<String,Object> politica(UUID doc){var rows=db.sql.queryForList("SELECT * FROM document_content_policy WHERE document_id=?",doc.toString());if(rows.isEmpty())throw new FalloTecnico(404);return rows.getFirst();}
    private long secuencia(String table,UUID cas){return db.sql.queryForObject("SELECT COALESCE(MAX(seq),0) FROM "+table+" WHERE case_id=?",Long.class,cas.toString());}
    private void propietario(UUID cas,UUID doc){propietario(cas,doc,false);}
    private void propietario(UUID cas,UUID doc,boolean aislado){var p=politica(doc);if(!cas.toString().equals(p.get("owner_case")))throw new FalloTecnico(404);if(!(aislado?Set.of("ORDINARIO","FIR").contains(p.get("classification")):"FIR".equals(p.get("classification"))))throw new FalloTecnico(409,aislado?"DOCUMENTO_REQUIERE_CLASIFICACION_ACREDITADA":"RESERVA_REQUIERE_FIR_ACREDITADA");}
    private void jefatura(Operador a,UUID cas){core.autorizarConsultaCaso(a,cas);core.head(a,core.caseRow(cas));persona(a.id());}
    private boolean cubre(FacultadReserva f,Map<String,Object> c){return f.estado().equals("ACTIVA")&&!f.desde().isAfter(clock.instant())&&f.hasta().isAfter(clock.instant())&&f.unidad().equals(c.get("unit_code"))&&f.sede().equals(c.get("site_id"))&&Objects.equals(f.area(),areas.area(c))&&Objects.equals(f.materia(),new PoliticaMaterias(db,clock).materia(u(c.get("id"))));}
    private boolean directo(Map<String,Object> r){return "SOLO_DOCUMENTO".equals(r.get("scope_mode"));}
    private FacultadReserva facultad(String actor,Map<String,Object> c){return facultad(actor,c,false);}
    private FacultadReserva facultad(String actor,Map<String,Object> c,boolean directa){if(autoridad==null)throw new FalloTecnico(409,"AUTORIDAD_RESERVA_NO_ACREDITADA");var ctx=directa?autoridad.contextoDocumentoAislado(actor):autoridad.contextoReserva(actor);return ctx.facultades().stream().filter(f->f.persona().equals(ctx.persona())&&cubre(f,c)).findFirst().orElseThrow(()->new FalloTecnico(404));}
    private List<Object> sello(Map<String,Object> r){var values=new ArrayList<Object>(Arrays.asList(r.get("document_id"),r.get("case_id"),r.get("policy_revision"),r.get("area_seq"),r.get("matter_seq"),r.get("unit_code"),r.get("site_id"),r.get("area_id"),r.get("matter_id"),r.get("requested_by"),r.get("requested_person"),r.get("request_authority"),r.get("beneficiary_id"),r.get("beneficiary_person"),r.get("requested_ms"),r.get("from_ms"),r.get("until_ms"),r.get("content_allowed"),r.get("download_allowed"),r.get("reason_text")));if(directo(r))values.add("SOLO_DOCUMENTO_1.7");return values;}
    private Map<String,Object> fila(UUID id){var rows=db.sql.queryForList("SELECT * FROM institution_sensitive_access WHERE id=?",id.toString());if(rows.isEmpty())throw new FalloTecnico(404);var r=rows.getFirst();if(!hash(sello(r)).equals(r.get("request_hash")))throw new FalloTecnico(409,"INSTRUCCION_ALTERADA");return r;}
    private void contexto(Map<String,Object> r){UUID cas=u(r.get("case_id")),doc=u(r.get("document_id"));propietario(cas,doc,directo(r));var p=politica(doc);var c=core.caseRow(cas);if(n(p,"revision")!=n(r,"policy_revision")||secuencia("case_area_history",cas)!=n(r,"area_seq")||secuencia("case_matter_history",cas)!=n(r,"matter_seq")||!Objects.equals(c.get("unit_code"),r.get("unit_code"))||!Objects.equals(c.get("site_id"),r.get("site_id"))||!Objects.equals(areas.area(c),r.get("area_id"))||!Objects.equals(new PoliticaMaterias(db,clock).materia(cas),r.get("matter_id")))throw new FalloTecnico(409,"AUTORIZACION_DOCUMENTAL_OBSOLETA");jefatura(cat.operador(s(r,"requested_by")),cas);if(!core.contenidos().permisosInstitucionales(cat.operador(s(r,"requested_by")),cas,doc).contenido())throw new FalloTecnico(404);if(!persona(s(r,"requested_by")).equals(r.get("requested_person"))||!persona(s(r,"beneficiary_id")).equals(r.get("beneficiary_person")))throw new FalloTecnico(409,"ACREDITACION_OBSOLETA");if(!directo(r))core.autorizarConsultaCaso(cat.operador(s(r,"beneficiary_id")),cas);}
    private void independiente(String actor,Map<String,Object> r){String person=persona(actor);if(person.equals(r.get("requested_person"))||person.equals(r.get("beneficiary_person")))throw new FalloTecnico(403,"SEPARACION_DE_FUNCIONES_REQUERIDA");}
    private void sinCiclo(String approver,Map<String,Object> r){
        var edges=new ArrayList<Map<String,Object>>(db.sql.queryForList("SELECT approver_person AS source_person,beneficiary_person AS target_person FROM access_instruction WHERE state IN ('APROBADA','EJECUTADA') AND valid_until>? AND valid_from<? AND valid_until>?",clock.millis(),r.get("until_ms"),r.get("from_ms")));
        edges.addAll(db.sql.queryForList("SELECT authorized_person AS source_person,beneficiary_person AS target_person FROM institution_sensitive_access WHERE state='ACTIVA' AND until_ms>? AND from_ms<? AND until_ms>? UNION ALL SELECT requested_person AS source_person,beneficiary_person AS target_person FROM institution_sensitive_access WHERE state='ACTIVA' AND until_ms>? AND from_ms<? AND until_ms>?",clock.millis(),r.get("until_ms"),r.get("from_ms"),clock.millis(),r.get("until_ms"),r.get("from_ms")));
        Map<String,List<String>> graph=new HashMap<>();for(var e:edges)if(e.get("source_person")!=null&&e.get("target_person")!=null)graph.computeIfAbsent(s(e,"source_person"),k->new ArrayList<>()).add(s(e,"target_person"));var queue=new ArrayDeque<String>();var seen=new HashSet<String>();queue.add(s(r,"beneficiary_person"));while(!queue.isEmpty()){String next=queue.remove();if(next.equals(approver))throw new FalloTecnico(403,"APROBACION_CRUZADA_NO_PERMITIDA");if(seen.add(next))queue.addAll(graph.getOrDefault(next,List.of()));}
    }
    public Resultado proponer(Operador a,UUID key,UUID cas,UUID doc,Proponer r){return proponerEnAmbito(a,key,cas,doc,r,false);}
    public Resultado proponerDocumento(Operador a,UUID key,UUID cas,UUID doc,Proponer r){return proponerEnAmbito(a,key,cas,doc,r,true);}
    private Resultado proponerEnAmbito(Operador a,UUID key,UUID cas,UUID doc,Proponer r,boolean soloDocumento){return intento(a,doc,"PROPONER",()->{
        if(r==null||r.beneficiario()==null||r.desde()==null||r.hasta()==null||!r.hasta().isAfter(r.desde())||!r.hasta().isAfter(clock.instant())||r.descarga()&&!r.contenido())throw new FalloTecnico(400);motivo(r.fundamento());jefatura(a,cas);
        return core.execute(key,a,soloDocumento?"PROPONER_DOCUMENTO_AISLADO":"PROPONER_ACCESO_RESERVADO",List.of(cas,doc,r),()->{guard(a);core.lock(u(core.caseRow(cas).get("communication_id")));jefatura(a,cas);propietario(cas,doc,soloDocumento);var p=politica(doc);version(p,r.revision());core.contenidos().autorizarDocumento(a,cas,doc,"CONTENIDO");String beneficiary=persona(r.beneficiario()),head=persona(a.id());if(beneficiary.equals(head))throw new FalloTecnico(403,"SEPARACION_DE_FUNCIONES_REQUERIDA");if(!soloDocumento)core.autorizarConsultaCaso(cat.operador(r.beneficiario()),cas);var c=core.caseRow(cas);
            if((soloDocumento?autoridad.contextoDocumentoAislado(a.id()):autoridad.contextoReserva(a.id())).facultades().stream().noneMatch(f->cubre(f,c)&&!f.persona().equals(head)&&!f.persona().equals(beneficiary)&&!r.desde().isBefore(f.desde())&&!r.hasta().isAfter(f.hasta())))throw new FalloTecnico(409,"AUTORIDAD_RESERVA_NO_ACREDITADA");temporales();if(db.sql.queryForObject("SELECT COUNT(*) FROM institution_sensitive_access WHERE document_id=? AND case_id=? AND beneficiary_id=? AND active_slot=1",Long.class,doc.toString(),cas.toString(),r.beneficiario())>0)throw new FalloTecnico(409,"ACCESO_RESERVADO_PENDIENTE");
            UUID id=UUID.randomUUID();var values=Arrays.asList(doc.toString(),cas.toString(),n(p,"revision"),secuencia("case_area_history",cas),secuencia("case_matter_history",cas),c.get("unit_code"),c.get("site_id"),areas.area(c),new PoliticaMaterias(db,clock).materia(cas),a.id(),head,autoridad.contextoReserva(a.id()).revision(),r.beneficiario(),beneficiary,clock.millis(),r.desde().toEpochMilli(),r.hasta().toEpochMilli(),r.contenido(),r.descarga(),r.fundamento());var args=new ArrayList<Object>();args.add(id.toString());args.addAll(values);var sealed=new ArrayList<Object>(values);if(soloDocumento)sealed.add("SOLO_DOCUMENTO_1.7");args.add(hash(sealed));String insert="INSERT INTO institution_sensitive_access(id,document_id,case_id,policy_revision,area_seq,matter_seq,unit_code,site_id,area_id,matter_id,requested_by,requested_person,request_authority,beneficiary_id,beneficiary_person,requested_ms,from_ms,until_ms,content_allowed,download_allowed,reason_text,request_hash,state,revision,active_slot) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'PENDIENTE',0,1)";if(soloDocumento){insert=insert.replace("active_slot)","active_slot,scope_mode)").replace("'PENDIENTE',0,1)","'PENDIENTE',0,1,?)");args.add("SOLO_DOCUMENTO");}db.sql.update(insert,args.toArray());historia(a,id,"RESERVA_PROPUESTA",r.fundamento());return new Resultado(id,0);
        });});}
    public Resultado decidir(Operador a,UUID key,UUID id,Decidir r,String action){return intento(a,id,action,()->{if(r==null||!Set.of("APROBAR","RECHAZAR","REVOCAR","RETIRAR").contains(action))throw new FalloTecnico(400);motivo(r.fundamento());autorizarDecision(a,fila(id),action);return core.execute(key,a,"RESERVA_"+action,List.of(id,r),()->{guard(a);var row=fila(id);core.lock(u(core.caseRow(u(row.get("case_id"))).get("communication_id")));autorizarDecision(a,row,action);version(row,r.revision());String state=s(row,"state");
        if(action.equals("APROBAR")||action.equals("RECHAZAR")){if(!state.equals("PENDIENTE"))throw new FalloTecnico(409);if(action.equals("APROBAR")){contexto(row);var f=facultad(a.id(),core.caseRow(u(row.get("case_id"))),directo(row));if(n(row,"until_ms")<=clock.millis()||n(row,"from_ms")<f.desde().toEpochMilli()||n(row,"until_ms")>f.hasta().toEpochMilli())throw new FalloTecnico(409,"APROBACION_NO_VIGENTE");sinCiclo(persona(a.id()),row);sinCiclo(s(row,"requested_person"),row);db.sql.update("UPDATE institution_sensitive_access SET state='ACTIVA',revision=revision+1,authorized_by=?,authorized_person=?,authorized_ms=?,capability_id=?,capability_hash=?,authority_revision=?,basis_ref=?,basis_sha256=?,decision_text=? WHERE id=?",a.id(),persona(a.id()),clock.millis(),f.id(),hash(f),autoridad.contextoReserva(a.id()).revision(),f.referencia(),f.sha256(),r.fundamento(),id.toString());}else terminar(a,id,r,"RECHAZADA");}
        else{if(action.equals("RETIRAR")?!state.equals("PENDIENTE"):!Set.of("ACTIVA","PENDIENTE").contains(state))throw new FalloTecnico(409);terminar(a,id,r,action.equals("RETIRAR")?"RETIRADA":"REVOCADA");}historia(a,id,"RESERVA_"+action,r.fundamento());return new Resultado(id,r.revision()+1);});});}
    private void autorizarDecision(Operador a,Map<String,Object> r,String action){core.bloquearAcceso(a);if(action.equals("RETIRAR")){jefatura(a,u(r.get("case_id")));return;}if(action.equals("REVOCAR")){try{jefatura(a,u(r.get("case_id")));return;}catch(FalloTecnico e){if(!Set.of(403,404,409).contains(e.status))throw e;}}facultad(a.id(),core.caseRow(u(r.get("case_id"))),directo(r));independiente(a.id(),r);}
    private void terminar(Operador a,UUID id,Decidir r,String state){db.sql.update("UPDATE institution_sensitive_access SET state=?,revision=revision+1,active_slot=NULL,ended_by=?,ended_ms=?,end_reason=? WHERE id=?",state,a.id(),clock.millis(),r.fundamento(),id.toString());}
    private void vigente(Map<String,Object> r){if(!"ACTIVA".equals(r.get("state"))||n(r,"from_ms")>clock.millis()||n(r,"until_ms")<=clock.millis())throw new FalloTecnico(404);contexto(r);String actor=s(r,"authorized_by");independiente(actor,r);var f=facultad(actor,core.caseRow(u(r.get("case_id"))),directo(r));if(!f.id().equals(r.get("capability_id"))||!hash(f).equals(r.get("capability_hash"))||!persona(actor).equals(r.get("authorized_person")))throw new FalloTecnico(404);}
    ContenidoInstitucional.Permisos permiso(Operador a,UUID cas,UUID doc){
        if(autoridad==null||cas==null)return null;try{if(autoridad.contextoReserva(a.id()).facultades().isEmpty())return null;core.autorizarConsultaCaso(a,cas);for(var r:db.sql.queryForList("SELECT id FROM institution_sensitive_access WHERE document_id=? AND case_id=? AND beneficiary_id=? AND state='ACTIVA'",doc.toString(),cas.toString(),a.id())){var e=fila(u(r.get("id")));if(directo(e))continue;vigente(e);return new ContenidoInstitucional.Permisos(Boolean.TRUE.equals(e.get("content_allowed")),Boolean.TRUE.equals(e.get("download_allowed")),false,"FIR",false);}return null;}catch(FalloTecnico e){if(Set.of(401,403,404,409).contains(e.status))return null;throw e;}
    }
    private boolean head(Operador a,UUID cas){try{jefatura(a,cas);return true;}catch(FalloTecnico e){if(Set.of(401,403,404,409).contains(e.status))return false;throw e;}}
    private boolean gi(Operador a,Map<String,Object> r){try{facultad(a.id(),core.caseRow(u(r.get("case_id"))),directo(r));return true;}catch(FalloTecnico e){if(Set.of(401,403,404,409).contains(e.status))return false;throw e;}}
    private boolean lector(Operador a,Map<String,Object> r){if(!a.id().equals(r.get("beneficiary_id")))return false;try{if(!persona(a.id()).equals(r.get("beneficiary_person")))return false;if(!directo(r))core.autorizarConsultaCaso(a,u(r.get("case_id")));return true;}catch(FalloTecnico e){if(Set.of(401,403,404,409).contains(e.status))return false;throw e;}}
    private boolean visible(Operador a,Map<String,Object> r){var c=core.caseRow(u(r.get("case_id")));return head(a,u(r.get("case_id")))||gi(a,r)||lector(a,r);}
    private Map<String,Object> vista(Operador a,Map<String,Object> r){var out=new LinkedHashMap<String,Object>();for(String k:List.of("id","case_id","state","revision","beneficiary_id","requested_by","authorized_by","requested_ms","from_ms","until_ms","content_allowed","download_allowed","ended_ms"))out.put(k,r.get(k));boolean head=head(a,u(r.get("case_id"))),authority=gi(a,r);if(head||authority){for(String k:List.of("document_id","reason_text","decision_text","end_reason","basis_ref","basis_sha256","request_hash","unit_code","site_id","area_id","matter_id"))out.put(k,r.get(k));out.put("historial",db.sql.queryForList("SELECT actor_id,action_code,at_ms FROM authority_event WHERE resource_id=? ORDER BY seq",r.get("id")));}boolean independent=!persona(a.id()).equals(r.get("requested_person"))&&!persona(a.id()).equals(r.get("beneficiary_person"));out.put("aprobar",authority&&independent&&"PENDIENTE".equals(r.get("state")));out.put("retirar",head&&"PENDIENTE".equals(r.get("state")));out.put("revocar",(head||authority&&independent)&&Set.of("PENDIENTE","ACTIVA").contains(r.get("state")));boolean active=false;try{vigente(r);active=true;}catch(FalloTecnico e){if(!Set.of(401,403,404,409).contains(e.status))throw e;}out.put("beneficiarioNombre",db.sql.queryForObject("SELECT label FROM core_actor WHERE id=?",String.class,r.get("beneficiary_id")));out.put("vigente",active);out.put("scope_mode",directo(r)?"SOLO_DOCUMENTO":"CASO_DOCUMENTO");out.put("consultarDocumento",active&&directo(r)&&a.id().equals(r.get("beneficiary_id")));if(directo(r)&&!head&&!authority)out.remove("case_id");return out;}
    public List<Map<String,Object>> bandeja(Operador a){return db.transaction(()->{guard(a);temporales();var result=new ArrayList<Map<String,Object>>();for(var row:db.sql.queryForList("SELECT * FROM institution_sensitive_access ORDER BY requested_ms DESC,id"))if(visible(a,row))result.add(vista(a,fila(u(row.get("id")))));new PoliticaMaterias(db,clock).auditar(a,a.id(),"CONSULTAR_ACCESOS_RESERVADOS");return result;});}
    public Map<String,Object> contexto(Operador a,UUID cas,UUID doc){return contextoEnAmbito(a,cas,doc,false);}
    public Map<String,Object> contextoDocumento(Operador a,UUID cas,UUID doc){return contextoEnAmbito(a,cas,doc,true);}
    private Map<String,Object> contextoEnAmbito(Operador a,UUID cas,UUID doc,boolean aislado){return db.transaction(()->{guard(a);jefatura(a,cas);propietario(cas,doc,aislado);var p=politica(doc);var c=core.caseRow(cas);var eligible=new ArrayList<String>();for(var candidate:cat.operadores())try{if(persona(candidate.id()).equals(persona(a.id())))continue;core.autorizarConsultaCaso(candidate,cas);eligible.add(candidate.id());}catch(FalloTecnico e){if(!Set.of(401,403,404,409).contains(e.status))throw e;}return Map.of("revision",n(p,"revision"),"beneficiarios",eligible,"gestionAcreditada",autoridad.contextoReserva(a.id()).facultades().stream().anyMatch(f->cubre(f,c)),"gestionDocumentoAcreditada",autoridad.contextoDocumentoAislado(a.id()).facultades().stream().anyMatch(f->cubre(f,c)));});}
    public boolean autorizarAviso(Operador a,UUID id){return db.transaction(()->{core.bloquearAcceso(a);return visible(a,fila(id));});}
    public Map<String,Object> destinatarioDocumento(Operador a,UUID cas,UUID doc,String usuario){return db.transaction(()->{guard(a);jefatura(a,cas);propietario(cas,doc,true);if(usuario==null||usuario.isBlank()||usuario.length()>80)throw new FalloTecnico(400);if(autoridad.contextoDocumentoAislado(a.id()).facultades().stream().noneMatch(f->cubre(f,core.caseRow(cas))&&!f.persona().equals(persona(a.id()))))throw new FalloTecnico(409,"AUTORIDAD_DOCUMENTO_AISLADO_NO_ACREDITADA");var users=db.sql.queryForList("SELECT actor_id FROM staff_account WHERE username=?",usuario);if(users.size()!=1)throw new FalloTecnico(404);String target=s(users.getFirst(),"actor_id");String person=persona(target);if(person.equals(persona(a.id())))throw new FalloTecnico(403,"SEPARACION_DE_FUNCIONES_REQUERIDA");new PoliticaMaterias(db,clock).auditar(a,doc.toString(),"DESTINATARIO_DOC_CONSULTADO");return Map.of("id",target,"nombre",cat.operador(target).nombre());});}
    public Consulta documentoAislado(Operador a,UUID id,String accion,boolean apertura){return intento(a,id,"CONSULTAR_DOCUMENTO",()->{
        try{return db.transaction(()->{guard(a);var r=fila(id);if(!directo(r)||!a.id().equals(r.get("beneficiary_id"))||!persona(a.id()).equals(r.get("beneficiary_person")))throw new FalloTecnico(404);vigente(r);if(!Set.of("METADATOS","CONTENIDO","DESCARGA").contains(accion))throw new FalloTecnico(400);boolean hold=cl.nexbyte.siger.institucional.documental.DisponibilidadDocumental.retenido(db,u(r.get("document_id")));if(hold&&!accion.equals("METADATOS"))throw new FalloTecnico(423,"DOCUMENTO_AISLADO_TECNICAMENTE");boolean content=!hold&&Boolean.TRUE.equals(r.get("content_allowed")),download=!hold&&Boolean.TRUE.equals(r.get("download_allowed"));if(accion.equals("CONTENIDO")&&!content||accion.equals("DESCARGA")&&!download)throw new FalloTecnico(404);if(apertura)new PoliticaMaterias(db,clock).auditar(a,s(r,"document_id"),"DOCUMENTO_AISLADO_"+accion);return new Consulta(u(r.get("document_id")),u(r.get("case_id")),content,download,hold);});}
        catch(FalloTecnico e){if(Set.of(403,404,409).contains(e.status))throw new FalloTecnico(404);throw e;}
    });}
    private void historia(Operador a,UUID id,String code,String reason){var r=fila(id);db.sql.update("INSERT INTO authority_event(actor_id,resource_id,action_code,result_code,at_ms,snapshot_doc) VALUES(?,?,?,'REGISTRADA',?,?)",a.id(),id.toString(),code,clock.millis(),json.writeValueAsString(Map.of("fundamento",reason,"revision",r.get("revision"),"huella",r.get("request_hash"))));core.event(u(core.caseRow(u(r.get("case_id"))).get("communication_id")),"RESERVA_DOC",id,a,code);}
    private void temporales(){for(var row:db.sql.queryForList("SELECT * FROM institution_sensitive_access WHERE active_slot=1 AND until_ms<=?",clock.millis())){var r=fila(u(row.get("id")));db.sql.update("UPDATE institution_sensitive_access SET state='EXPIRADA',revision=revision+1,active_slot=NULL,ended_ms=? WHERE id=?",r.get("until_ms"),r.get("id"));db.sql.update("INSERT INTO authority_event(actor_id,resource_id,action_code,result_code,at_ms,snapshot_doc) VALUES(NULL,?,'RESERVA_EXPIRADA','VIGENCIA_TERMINADA',?,?)",r.get("id"),clock.millis(),json.writeValueAsString(Map.of("efectivaHasta",r.get("until_ms"),"registradaEn",clock.millis())));db.sql.update("INSERT INTO workflow_event(event_key,code,resource_type,resource_id,at_ms) VALUES(?,'CONTINUIDAD_DECIDIDA','RESERVA_DOC',?,?)",r.get("id")+":"+(n(r,"revision")+1)+":EXPIRADA",r.get("id"),clock.millis());}}
    private <T>T intento(Operador a,UUID resource,String action,Supplier<T> operation){try{return operation.get();}catch(FalloTecnico e){if(a!=null&&Set.of(403,404,409).contains(e.status)){db.sql.update("INSERT INTO authority_event(actor_id,resource_id,action_code,result_code,at_ms) VALUES(?,?,?,?,?)",a.id(),resource.toString(),"RESERVA_DENEGADA",action,clock.millis());}throw e;}}
